from math import ceil
L, K, LIMIT = 105, 65536, 7 * 1024 * 1024        # символов, записей, байт
for bits in range(1, 30):
    if ceil(L * bits / 8) * K > LIMIT:
        print('максимум бит на символ:', bits - 1, '→ алфавит до', 2 ** (bits - 1))
        break

